('c-001', 'Kaldırımda Derin Çukur', 'Saraçlar Caddesi girişinde kaldırım taşları sökülmüş ve derin bir çukur oluşmuş. Yaşlılar ve bebek arabaları için ciddi tehlike yaratıyor.', 'road_pavement', 'Yol / Kaldırım', 'pending', '2026-09-24T10:15:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.6775, 26.5552, 'Saraçlar Cad. No:14, Sabuni Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1515162816999-a0c47dc192f7?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1578991624414-276ef23a534f?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-101', 'Misafir Vatandaş #4129', TRUE, 18, 9, 0, '2026-10-08T10:15:00Z', NULL),
('c-002', 'Sokak Lambası 3 Gündür Yanmıyor', 'Talat Paşa Asfaltı üzerindeki 4 nolu aydınlatma direği akşamları hiç yanmıyor. Gece saatlerinde sokak tamamen karanlıkta kalıyor.', 'lighting', 'Sokak Aydınlatması', 'inReview', '2026-09-22T21:40:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.672, 26.562, 'Talat Paşa Asfaltı, Talatpaşa Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1509114397022-ed747cca3f65?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-102', 'Misafir Vatandaş #7821', TRUE, 12, 6, 0, '2026-09-29T21:40:00Z', NULL),
('c-003', 'Konteyner Taşmış, Çöpler Dağılmış', 'Şükrüpaşa Mahallesi İlhami Ertem Caddesi köşesindeki çöp konteynerleri günlerdir boşaltılmadı. Sokak hayvanları çöpleri etrafa yaymış.', 'waste_cleaning', 'Çöp / Temizlik', 'resolved', '2026-09-20T08:30:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.684, 26.571, 'İlhami Ertem Cad., Şükrüpaşa Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1605600659908-0ef719419d41?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-103', 'Misafir Vatandaş #2340', TRUE, 34, 15, 0, '2026-09-23T08:30:00Z', '2026-09-21T14:10:00Z'),
('c-004', 'Ana Su Borusu Patladı', 'Koca Sinan Mahallesi Dr. Sadık Ahmet Caddesi üzerinde temiz su borusu patladı, saatlerdir tonlarca su yola akıyor.', 'water_sewage', 'Su / Kanalizasyon', 'inReview', '2026-09-25T07:10:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.6685, 26.5815, 'Dr. Sadık Ahmet Cad., Koca Sinan Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1585687595561-ebae529a6e13?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-104', 'Misafir Vatandaş #9012', TRUE, 27, 18, 0, '2026-09-30T07:10:00Z', NULL),
('c-005', 'Çocuk Parkındaki Salıncak Kırık', 'Barış Parkı içerisindeki çocuk oyun alanında salıncak zinciri kopmuş durumda, demir aksam sivrilmiş. Çocuklar için tehlike saçıyor.', 'parks_green', 'Park / Yeşil Alan', 'pending', '2026-09-23T16:20:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.674, 26.549, 'Barış Parkı İçi, Fatih Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1519331379826-f10be5486c6f?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-105', 'Misafir Vatandaş #5531', TRUE, 15, 8, 0, '2026-10-03T16:20:00Z', NULL),
('c-006', 'Trafik Levhası Eğilmiş ve Görünmüyor', 'Dilaverbey Mahallesi Darülhadis Caddesi kavşağındaki Dur levhası rüzgardan eğilmiş, gelen sürücüler kavşağı göremiyor.', 'traffic_signs', 'Diğer', 'resolved', '2026-09-18T11:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.6795, 26.551, 'Darülhadis Cad., Dilaverbey Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-106', 'Misafir Vatandaş #3142', TRUE, 8, 4, 0, '2026-09-25T11:00:00Z', '2026-09-21T09:40:00Z'),
('c-007', 'Yaralı Sokak Köpeği İçin Yardım', 'Meriç Köprüsü yakınlarında sol arka ayağından yaralanmış bir köpek var, acil veteriner veya barınak ekiplerinin müdahale etmesi gerekiyor.', 'animals', 'Diğer', 'resolved', '2026-09-24T14:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.662, 26.558, 'Köprübaşı Mevkii, Karaağaç Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-107', 'Misafir Vatandaş #6610', TRUE, 42, 19, 0, '2026-09-29T14:00:00Z', '2026-09-25T10:30:00Z'),
('c-008', 'İnşaat Atıkları Yola Dökülmüş', 'Mithatpaşa Mahallesi ara sokağında kimliği belirsiz kişilerce moloz ve harç atıkları yolun yarısını kapatacak şekilde bırakılmış.', 'waste_cleaning', 'Çöp / Temizlik', 'pending', '2026-09-25T12:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.676, 26.5645, 'Gazi Paşa Sok., Mithatpaşa Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-108', 'Misafir Vatandaş #8754', TRUE, 9, 5, 0, '2026-09-28T12:00:00Z', NULL),
('c-009', 'Yağmur Suyu Mazgalı Tıkalı', 'Ayşekadın Karakolu önündeki ızgara yaprak ve balçıkla tıkanmış. Yağmur yağdığında caddeyi su basıyor.', 'water_sewage', 'Su / Kanalizasyon', 'inReview', '2026-09-21T18:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.669, 26.57, 'Ayşekadın Cad., 1. Murat Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-109', 'Misafir Vatandaş #1928', TRUE, 14, 7, 0, '2026-09-26T18:00:00Z', NULL),
('c-010', 'Asfalt Çökmesi Sonucu Araç Lastiği Hasar Gördü', 'Keşan Kurtuluş Caddesi üzerinde rögar kapağı çevresinde 20 cm çökme var. Hızla gelen araçlar çok sert çarpıyor.', 'road_pavement', 'Yol / Kaldırım', 'pending', '2026-09-23T09:15:00Z', 'muni_edirne_kesan', 'Edirne Belediyesi', 40.855, 26.634, 'Kurtuluş Cad. No:82, Keşan', ARRAY['https://images.unsplash.com/photo-1515162816999-a0c47dc192f7?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-110', 'Misafir Vatandaş #4421', TRUE, 22, 11, 0, '2026-10-07T09:15:00Z', NULL),
('c-011', 'Park Aydınlatması Çalışmıyor', 'Keşan Cennet Bahçesi parkında aydınlatma direkleri yanmıyor. Aileler akşam saatlerinde parka giremiyor.', 'lighting', 'Sokak Aydınlatması', 'resolved', '2026-09-15T20:00:00Z', 'muni_edirne_kesan', 'Edirne Belediyesi', 40.86, 26.638, 'Cennet Bahçesi Yanı, Keşan', ARRAY['https://images.unsplash.com/photo-1509114397022-ed747cca3f65?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-111', 'Misafir Vatandaş #7189', TRUE, 19, 8, 0, '2026-09-22T20:00:00Z', '2026-09-20T16:00:00Z'),
('c-012', 'Tarihi Taş Köprü Yanında Çöp Birikintisi', 'Uzunköprü Taş Köprü yürüyüş yolunda piknikçilerin bıraktığı çöpler toplanmamış ve nehir kenarına uçuşuyor.', 'waste_cleaning', 'Çöp / Temizlik', 'pending', '2026-09-24T15:30:00Z', 'muni_edirne_uzunkopru', 'Edirne Belediyesi', 41.271, 26.685, 'Köprü Yanı Rekreasyon Alanı, Uzunköprü', ARRAY['https://images.unsplash.com/photo-1605600659908-0ef719419d41?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-112', 'Misafir Vatandaş #3890', TRUE, 31, 14, 0, '2026-09-27T15:30:00Z', NULL),
('c-013', 'Parktaki Çimler Kurumuş ve Otlar Uzamış', 'Kocasinan Parkı''nda otomatik sulama sistemi arızalanmış, çimler sararmış ve yabani dikenli otlar çocukların boyunu aşmış.', 'parks_green', 'Park / Yeşil Alan', 'resolved', '2026-09-12T10:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.67, 26.578, 'Kocasinan Parkı, Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1519331379826-f10be5486c6f?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-113', 'Misafir Vatandaş #6541', TRUE, 16, 7, 0, '2026-09-22T10:00:00Z', '2026-09-17T11:00:00Z'),
('c-014', 'Özel Mülk Girişi Engeli (Hatalı Şikayet)', 'Apartmanımızın bahçesindeki kurumuş ağacın belediyece kesilmesini istiyoruz.', 'other', 'Diğer', 'rejected', '2026-09-19T13:40:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.681, 26.561, 'Barutluk Mah. 3. Sok., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-114', 'Misafir Vatandaş #2119', TRUE, 2, 1, 0, '2026-10-03T13:40:00Z', NULL),
('c-015', 'Okul Önü Hız Kesici Kasis Boyaları Silinmiş', 'Cumhuriyet İlkokulu önündeki kasisin sarı çizgileri silindiği için sürücüler yavaşlamıyor, okul çıkışında tehlike yaşanıyor.', 'traffic_signs', 'Diğer', 'inReview', '2026-09-22T08:00:00Z', 'muni_edirne_merkez', 'Edirne Belediyesi', 41.6755, 26.559, 'Cumhuriyet Cad., Sabuni Mah., Edirne Merkez', ARRAY['https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-115', 'Misafir Vatandaş #5920', TRUE, 38, 22, 0, '2026-09-29T08:00:00Z', NULL),
('c-016', 'Kaldırım İşgali ve Yaya Geçidi Kapatılmış', 'Çorlu Omurtak Caddesi''nde dükkan önü malzemeler kaldırımı tamamen tıkamış, yayalar mecburen araç yolundan yürümek zorunda kalıyor.', 'road_pavement', 'Yol / Kaldırım', 'resolved', '2026-09-20T11:20:00Z', 'muni_tekirdag_corlu', 'Edirne Belediyesi', 41.159, 27.801, 'Omurtak Cad., Şeyhsinan Mah., Çorlu', ARRAY['https://images.unsplash.com/photo-1578991624414-276ef23a534f?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-116', 'Misafir Vatandaş #8031', TRUE, 45, 29, 0, '2026-10-04T11:20:00Z', '2026-09-22T14:30:00Z'),
('c-017', 'Pazar Yeri Temizliği Yapılmamış', 'Lüleburgaz Kapalı Pazar Yeri kurulduktan sonra çöpler ve sebze artıkları yerde bırakılmış, kötü koku yayılıyor.', 'waste_cleaning', 'Çöp / Temizlik', 'resolved', '2026-09-23T19:00:00Z', 'muni_kirklareli_luleburgaz', 'Edirne Belediyesi', 41.405, 27.358, 'Kapalı Pazaryeri Mevkii, Lüleburgaz', ARRAY['https://images.unsplash.com/photo-1605600659908-0ef719419d41?w=800&auto=format&fit=crop&q=80']::text[], ARRAY[]::text[], NULL, NULL, NULL, 'user-117', 'Misafir Vatandaş #4719', TRUE, 28, 13, 0, '2026-09-26T19:00:00Z', '2026-09-24T08:00:00Z'),
